async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var laPalma = ee.Geometry.Polygon([
    [[-18.2, 28.4], [-17.7, 28.4], [-17.7, 29.0], [-18.2, 29.0], [-18.2, 28.4]]
  ]); // Bounding box around La Palma island

  var start1 = '2023-07-15';
  var end1 = '2023-07-17'; // exclusive, so covers 15-16
  var start2 = '2023-07-17';
  var end2 = '2023-07-19'; // exclusive, so covers 17-18

  // Function to get fire pixel count for a date range
  function getFireCount(startDate, endDate, geom) {
    // Try MODIS first
    var modis = ee.ImageCollection('MODIS/006/MCD14DL')
                  .filterDate(startDate, endDate)
                  .filterBounds(geom);
    var coll = modis;
    var band = 'confidence';
    var scale = 1000;

    // Check if MODIS has data
    if (modis.size().getInfo() === 0) {
      // Fallback to VIIRS
      var viirs = ee.ImageCollection('VIIRS/NOAA20/VNP14IMGTDL_NRT')
                    .filterDate(startDate, endDate)
                    .filterBounds(geom);
      if (viirs.size().getInfo() === 0) {
        return {count: null, images: 0, source: 'none'}; // No data
      }
      coll = viirs;
      band = 'confidence';
      scale = 375;
    }

    var img = coll.select(band).max(); // Maximum confidence in the period
    var fireMask = img.gt(0); // Binary mask where confidence > 0 (fire pixel)

    // Count fire pixels
    var count = fireMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9,
    }).get(band).getInfo();

    return {count: count, images: coll.size().getInfo(), source: coll.get('system:id').getInfo()};
  }

  // 2. Get counts for both periods
  var count1 = getFireCount(start1, end1, laPalma);
  var count2 = getFireCount(start2, end2, laPalma);

  // 3. Check for no data (C1)
  if (count1.count === null || count2.count === null) {
    console.log(`Period 1 (${start1} to ${end1}): ${count1.images} images (Source: ${count1.source})`);
    console.log(`Period 2 (${start2} to ${end2}): ${count2.images} images (Source: ${count2.source})`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Check for no valid pixels (C2) - count could be 0 (valid), but we check if images exist and count is 0
  if (count1.count === 0 && count1.images > 0) {
    // This is valid (no fires), not C2
  }
  if (count2.count === 0 && count2.images > 0) {
    // This is valid (no fires), not C2
  }

  // 5. Output evidence
  console.log(`Period 1 (${start1} to ${end1}): ${count1.images} images, Fire pixels: ${count1.count}`);
  console.log(`Period 2 (${start2} to ${end2}): ${count2.images} images, Fire pixels: ${count2.count}`);

  // 6. Compare and output answer
  if (count2.count < count1.count) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

